def gsl_factorize(n):
    libgslcblas.gsl_factorize.argtypes = [ctypes.c_longlong]
    libgslcblas.gsl_factorize.restype = ctypes.POINTER(ctypes.c_longlong)
    return libgslcblas.gsl_factorize(n)

def prime_factors(num):
    factors = set()
    i = 2
    while i <= math.sqrt(num):
        if num % i:
            i += 1
        else:
            num //= i
            while num % i == 0:
                num //= i
            factors.add(i)
    if num > 1:
        factors.add(num)
    return list(factors), len(factors)

def main(n):
    libgsl.gsl_fft_factorize.argtypes = [ctypes.POINTER(ctypes.c_longlong)]
    libgsl.gsl_fft_factorize.restype = None
    f = ctypes.c_longlong(n)
    libgsl.gsl_fft_factorize([f])
    factors, num_factors = prime_factors(n)
    return json.dumps({'factors': list(factors), 'num_factors': num_factors})

