class gsl_factorize(ctypes.Structure):
    _fields_ = [('size', ctypes.c_int), ('factors', ctypes.POINTER(ctypes.c_int))]

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def prime_factors(n):
    if n < 2:
        return [n]
    factors = defaultdict(int)
    for p in range(2, int(n**0.5) + 1):
        while n % p == 0:
            factors[p] += 1
            n //= p
    if n > 1:
        factors[n] = 1
    return list(factors.keys())

def fft_factorize(n, subtransforms):
    libgsl.gsl_factorize.restype = ctypes.POINTER(gsl_factorize)
    libgsl.gsl_factorize.argtypes = [ctypes.c_int]
    f = libgsl.gsl_factorize(n)
    factors = [f[0] for _ in range(f.contents.size)]
    libgsl.gsl_free_factorization.restype = None
    libgsl.gsl_free_factorization.argtypes = [gsl_factorize]
    libgsl.gsl_free_factorization(f)
    return [x for x in factors if x > 1], len([x for x in factors if x > 1])

def main(n):
    subtransforms = ctypes.c_double * (len(subtransforms) + 1)
    libgsl.fftfactorize.restype = ctypes.POINTER(gsl_factorize)
    libgsl.fftfactorize.argtypes = [ctypes.c_int, ctypes.POINTER(ctypes.c_double)]
    factors, size = fft_factorize(n, subtransforms)
    return json.dumps({'Candidate_solution': f'prime_factors({n}) = {prime_factors(n)}'})

