def compute_legendre_derivatives():
    libgslcblas = ctypes.CDLL('/usr/local/gsl/lib/libgslcblas.so', mode=ctypes.RTLD_GLOBAL)
    libgsl = ctypes.CDLL('/usr/local/gsl/lib/libgsl.so')
    libgsl.cblas_spmult.set_format(ctypes.c_double)

    def compute_legendre(n, x):
        if n == 0:
            return 1.0
        elif n % 2 == 1:
            return 0.0
        else:
            return (2.0 * n - 1.0) / (n + 1.0) * x * compute_legendre(n-1, x)

    def first_derivative_legendre(n, x):
        if n == 0:
            return 0.0
        elif n % 2 == 1:
            return 0.0
        else:
            return (2.0 * n - 1.0) / (n + 1.0) * (x * compute_legendre(n-1, x) + compute_legendre(n, x))

    def second_derivative_legendre(n, x):
        if n == 0:
            return 0.0
        elif n % 2 == 1:
            return 0.0
        else:
            return (2.0 * n - 3.0) / (n + 1.0) * (x * compute_legendre(n-1, x) + compute_legendre(n, x)) - (2.0 * n - 1.0) / (n + 1.0) ** 2 * compute_legendre(n-1, x)

    result = []
    for n in range(10):
        for x in np.arange(-0.99, 1.00, 0.01):
            value = compute_legendre(n, x)
            first_derivative = first_derivative_legendre(n, x)
            second_derivative = second_derivative_legendre(n, x)
            result.append((x, value, first_derivative, second_derivative))
    return json.dumps(result)

