    assert len(jacobian) == num_cols and all(len(row) == len(jacobian[0]) for row in jacobian), \"Invalid Jacobian shape\"

    # Allocate GSL matrices
    jacobians = [GSLMatrix.alloc(1, len(jacobian[0])) for _ in range(num_cols)]
    for i in range(num_cols):
        GSLMatrix.from_numpy(np.array([jacobian[i]]).T).to_gsl().copy_to_(jacobians[i])

    # Compute covariance matrix
    covariances = GSLMatrix.alloc(num_cols, num_cols)
    gsl.gsl_multifit_covar(jacobians[0].ptr, jacobians[1].ptr, epsrel, covariances.ptr)

    # Free GSL matrices and return the result
    for j in jacobians:
        GSLMatrix.free(j)
    return GSLMatrix.to_numpy(covariances).tolist()

