class GSLVector:
    def __init__(self, size):
        self.size = size
        self.vec = np.zeros(size, dtype=float)
        self.gsl_vector_ptr = gsl.vector_alloc(size)
        for i in range(self.size):
            self.set_element(i, c_double(self.vec[i]))

    def set_element(self, index, value):
        gsl.vector_set(self.gsl_vector_ptr, index, value.value)

    def print_vector(self):
        for i in range(self.size):
            print(gsl.vector_get(self.gsl_vector_ptr, i))

    def __del__(self):
        gsl.vector_free(self.gsl_vector_ptr)

def create_and_print_vector(size):
    vec = GSLVector(size)
    vec.print_vector()

