    try:
        if len(input_data) > 0 and type(t) == float and type(K) == int and 0 < K <= len(input_data)
            input_gsl = create_gsl_vector(input_data)
            output_gsl = gsl.filter_impulse_alloc(len(input_data), 0, t, K)
            for i in range(len(input_data)):
                if np.abs(gsl.gaussian_1d_get(input_gsl, i) - t) > t:
                    gsl.filter_impulse(output_gsl, i, gsl.gaussian_1d_get(input_gsl, i), 0, t)
