    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols

    def _allocate(self):
        self.data = (ctypes.c_double * (self.rows * self.cols))()

    def to_numpy(self):
        return np.array([[self.data[i*self.cols + j] for j in range(self.cols)] for i in range(self.rows)])

    def free(self):
        del self.data

def list_to_ctypes_matrix(lst):
    rows = len(lst)
    cols = len(lst[0])
    matrix = GSLMatrix(rows, cols)
    matrix._allocate()
    for i in range(rows):
        for j in range(cols):
            matrix.data[i*cols + j] = lst[i][j]
    return matrix

def compute_covariance(jacobian, epsrel):
