    jacobian_ptr = jacobian._allocate()
    covar_ptr = (ctypes.c_double * 1)()

    gsl.gsl_multifit_nlinear_covar.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int, ctypes.POINTER(ctypes.c_double)]
    gsl.gsl_multifit_nlinear_covar.restype = ctypes.c_double

    result = gsl.gsl_multifit_nlinear_covar(jacobian_ptr, jacobian.rows, jacobian.cols, covar_ptr)

    covariance_matrix = GSLMatrix(jacobian.rows, jacobian.cols)
    covariance_matrix._allocate()
    for i in range(covariance_matrix.rows):
        for j in range(covariance_matrix.cols):
            covariance_matrix.data[i*covariance_matrix.cols + j] = result[0]

