class GSLMatrix:
    def __init__(self):
        self.gsl_matrix = None

    def create_gsl_matrix(self, data):
        num_rows = len(data)
        num_cols = len(data[0])
        self.gsl_matrix = gsl.gsl_matrix_calloc(num_rows, num_cols)
        for i in range(num_rows):
            for j in range(num_cols):
                gsl.gsl_matrix_set(self.gsl_matrix, i, j, data[i][j])

    def retrieve_gsl_matrix(self):
        result = []
        num_rows = int(gsl.gsl_matrix_get_size(self.gsl_matrix, 0))
        num_cols = int(gsl.gsl_matrix_get_size(self.gsl_matrix, 1))
        for i in range(num_rows):
            row = []
            for j in range(num_cols):
                row.append(float(gsl.gsl_matrix_get(self.gsl_matrix, i, j)))
            result.append(row)
        return result

    def free_gsl_matrix(self):
        gsl.gsl_matrix_free(self.gsl_matrix)

