class C_GSL_Function(ctypes.Structure):
    _fields_ = [('function', ctypes.CFUNCTYPE(None, ctypes.c_double, ctypes.POINTER(ctypes.c_void_p))),
                ('params', ctypes.c_void_p)]

gsl_function_ptr_type = ctypes.CFUNCTYPE(None, ctypes.c_double, ctypes.POINTER(C_GSL_Function))

def func_wrapper(x, params):
    my_func, a, b, epsabs, epsrel, n = ctypes.cast(params, ctypes.POINTER((ctypes.c_double * 6))).contents
