class Vector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(ctypes.c_double))]

def compute_minmax(data):
    n = len(data)
    arr = (ctypes.c_double * n) (*data)
    vector = Vector(arr.ctypes.data)
    result = blas.cblas_dminmax(1, n, ctypes.byref(vector), None)
    return float(result[0]), float(result[1])

def main(data):
    min_val, max_val = compute_minmax(data)
    return (min_val, max_val)

